/*
 * Utility chip: a Lifted Charcoal fill with a 1px Seam border, only inside
 * utility drawers, the modal attachment chooser, recovery banners and the
 * synthetic workspace strip. Same 24px height as the ghost button.
 */
:where(.utility-drawer, .attachment-chooser, .recovery-banner, .header-alert, .workspace-header) :where(button) {
  background: var(--surface-raised);
  border: 1px solid var(--divider);
  padding: 3px 8px;
}

:where(.utility-drawer, .attachment-chooser, .recovery-banner, .header-alert, .workspace-header) :where(button:not(:disabled):hover) {
  background: var(--focus-fill);
}

button:focus-visible {
  outline: 2px solid var(--focus-accent);
.search-gloss { font-size: var(--type-body); color: var(--text-secondary); }
.mail-search p.search-unsupported { margin: 4px 0 0; font-size: var(--type-count); color: var(--text-tertiary); }
/* Coverage / continuation-error lines live outside the form so they stay
 * visible in search context while the entry form is collapsed. */
.search-coverage, .search-inline-error { margin: 0; padding: 6px 24px 6px 50px; max-width: calc(75ch + 74px); font-size: var(--type-body); color: var(--text-secondary); }
.search-inline-error { color: var(--danger); }
/*
 * Utility disclosures overlay the central surface; they are never columns.
 * They start below the split header (positioned against .app-main), so the
 * header's right-hand glyphs (Commands, Search, filters) are never covered
 * by an open drawer.
 */
.utility-drawer {
  position: absolute;
  top: var(--split-header-height);
  right: 0;
  bottom: 0;
  width: min(460px, 92vw);
  background: var(--surface-contact);
  border-left: 1px solid var(--divider);
  box-shadow: -8px 0 24px rgba(0, 0, 0, 0.35);
  overflow-y: auto;
  padding: 0.5rem 0.75rem;
  z-index: 30;
}

.utility-drawer:focus {
  outline: none;
}

.drawer-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.5rem;
  margin-bottom: 0.4rem;
}

.drawer-header h2 {
  font-size: var(--type-headline);
  font-weight: var(--weight-regular);
  margin: 0;
}

/*
 * Compact conversation list (DESIGN.md "Conversation Row"): 36px rows on 12px
 * type in two weights, separated by rhythm alone (no per-row dividers). The
 * row highlight is inset 6px from both pane edges; the 44px left gutter holds
 * the selection checkbox and the read marker, so sender names, date captions
 * and the split tabs share the 50px content inset.
 */
.inbox-scroll {
  list-style: none;
  margin: 0;
  padding: 0;
  overflow-y: auto;
  margin: 12px 0 0;
  font-size: var(--type-body);
  color: var(--text-secondary);
}

/* Activity (inside its utility disclosure). */
/* In-panel headings are Title labels under the drawer's Headline. */
.activity-title {
  font-size: var(--type-body);
  font-weight: var(--weight-strong);
  margin: 0 0 0.5rem;
}

.activity-list {
  list-style: none;
  margin: 0;
  padding: 0;
}

.activity-row {
  border-bottom: 1px solid var(--rule);
  padding: 0.4rem 0;
  font-size: var(--type-body);
  display: flex;
  flex-direction: column;
  gap: 0.2rem;
}

.status-queued,
.status-applying {
