/* "Draft" state flag: plain strong text, never uppercase/tracked and never a
   second accent — the reader's active-message bar already owns focus-accent. */
.draft-flag {
  color: var(--text-primary);
  font-weight: var(--weight-strong);
}

/* Composer footer, shared by the inline compose card, the docked reply
   composer and the drafts-drawer editor: actions right-aligned above a rule. */
.composer-footer {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  flex-wrap: wrap;
  margin-top: 0.4rem;
  padding-top: 0.5rem;
  border-top: 1px solid var(--rule);
}

/* Primary: Focus Stone fill, Title weight, 4px radius, 24px tall. Hover adds an
   Ash inset ring (the fill alone is invisible against the raised surface). */
.composer-footer .composer-primary {
  background: var(--focus-fill);
  color: var(--text-primary);
  border: 0;
  border-radius: 4px;
  padding: 4px 8px;
  font-weight: var(--weight-strong);
}

.composer-footer .composer-primary:hover:not(:disabled) {
  background: var(--focus-fill);
  box-shadow: inset 0 0 0 1px var(--text-secondary);
}

.composer-footer .composer-primary:active:not(:disabled) {
  background: var(--rail-button);
  box-shadow: inset 0 0 0 1px var(--text-secondary);
}

.composer-kbd {
  margin-left: -0.25rem;
  color: var(--text-secondary);
  font: inherit;
}

/* Secondary actions: quiet Ash ghosts. */
.composer-footer .composer-quiet {
  background: transparent;
  color: var(--text-secondary);
  border: 0;
  padding: 4px 8px;
}

.composer-footer .composer-quiet:hover:not(:disabled) {
  background: var(--focus-fill);
  color: var(--text-primary);
}

.composer-footer .composer-discard {
  margin-left: auto;
}

/* Inline confirm dialog (discard / reload) on any composer surface. */
.discard-confirm {
  border: 1px solid var(--rule);
  border-radius: 6px;
  padding: 0.4rem 0.6rem;
  display: flex;
  flex-direction: column;
  gap: 0.3rem;
  align-items: center;
  gap: 0.5rem;
  min-width: 0;
  min-height: 28px;
  font-size: var(--type-body);
}

.field-label {
  flex: 0 0 3.5rem;
  color: var(--text-secondary);
}

.field-row .field-input,
.field-row .field-summary {
  flex: 1 1 auto;
  min-width: 0;
  padding: 3px 6px;
  font: inherit;
}

/* A quiet Seam underline at rest so an empty row still shows where to type;
   the full Seam border returns on hover (DESIGN.md "Inputs / Fields"). */
.field-row .field-input {
  background: transparent;
  border: 1px solid transparent;
  border-bottom-color: var(--divider);
  border-radius: 4px;
}

.field-row .field-input:hover:not(:disabled) {
  border-color: var(--divider);
}

.field-row .field-input:focus-visible {
  border-color: var(--focus-accent);
  outline: 1px solid var(--focus-accent);
  outline-offset: -2px;
}

/* The collapsed reply recipient: a real button that opens the To input. */
.field-row .field-summary {
  text-align: left;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  color: var(--text-primary);
}

.field-row .field-summary:hover:not(:disabled) {
  background: var(--focus-fill);
}

.field-toggle {
  flex: none;
  color: var(--text-secondary);
}

.field-toggle:hover:not(:disabled) {
  color: var(--text-primary);
}

.field-body {
  display: flex;
  flex-direction: column;
  min-width: 0;
  margin-top: 0.25rem;
}

.field-textarea {
  width: 100%;
  min-width: 0;
  /* At least six lines at the 12px body size; grows with its text up to the pane. */
  min-height: 7.5rem;
  max-height: 50vh;
  padding: 6px 8px;
  resize: vertical;
  white-space: pre-wrap;
  font: inherit;
  line-height: var(--leading-ui);
}

