    if (index === -1) return;
    const next = move === 'first' ? 0
      : move === 'last' ? rows.length - 1
        : Math.min(rows.length - 1, Math.max(0, index + (move === 'next' ? 1 : -1)));
    event.preventDefault();
    const row = rows[next];
    if (!row || row === target) return;
